{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "Ensure that detailed monitoring is enabled for EC2 instances",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "Detailed monitoring is not enabled for this EC2 instance. Without it, you may lack critical performance metrics for monitoring and troubleshooting."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "Instance Metadata Service Version 1 is less secure and susceptible to SSRF attacks. IMDSv2 should be enforced to mitigate this risk."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The root EBS volume is not explicitly encrypted. Unencrypted volumes can expose sensitive data if compromised."
    },
    {
      "check_id": "CKV2_AWS_41",
      "title": "Ensure an IAM role is attached to EC2 instance",
      "resource": "aws_instance.web",
      "severity": "MEDIUM",
      "explanation": "The EC2 instance does not have an IAM role attached. This limits the ability to securely access AWS services without embedding credentials."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"web\" {\n  ami                    = \"${var.ami}\"\n  instance_type          = \"t2.micro\"\n  subnet_id              = \"${aws_subnet.public-subnet.id}\"\n  vpc_security_group_ids = [\"${aws_security_group.sgweb.id}\"]\n\n  monitoring             = true\n\n  metadata_options {\n    http_tokens = \"required\"\n    http_endpoint = \"enabled\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n\n  iam_instance_profile = \"${aws_iam_instance_profile.web_profile.name}\"\n}",
  "fix_summary": "Enabled detailed monitoring for the EC2 instance, enforced IMDSv2 by setting metadata options, ensured the root EBS volume is encrypted, and attached an IAM instance profile to the EC2 instance."
}
